INSERT OR REPLACE INTO portal_anuncios (id, formato, activo, orden, desde, hasta, datos, autor, responsable, creado) VALUES ('anc-rmg78429wv', 'tarjeta', 1, 1, '2026-10-04T06:00:00.000Z', '2026-10-10T05:59:59.000Z', '{"tono":"info","titulo":"Queremos tu opinión: horario de la capacitación","descripcion":"Una pregunta rápida para decidir cuándo hacemos la próxima capacitación de cotizaciones.","imagenUrl":"","vigencia":"Responde antes del viernes 9 de octubre","encuesta":{"pregunta":"¿Qué horario te acomoda para la capacitación?","opciones":["Por la mañana","Después de comer","Al final del turno"],"tiempo":"30 segundos","cierre":"2026-10-09","verAntes":false}}', 'supervisora@ventel.example', 'Laura Domínguez', '2026-10-04T19:50:00.000Z');
INSERT OR REPLACE INTO portal_anuncios (id, formato, activo, orden, desde, hasta, datos, autor, responsable, creado) VALUES ('anc-l827xv1oai', 'banner', 1, 2, '2026-10-05T06:00:00.000Z', '2026-10-11T05:59:59.000Z', '{"tono":"warn","mensaje":"Mantenimiento programado: el sábado 10 de octubre, de 8:00 a 11:00 h, el sistema no estará disponible. Guarda y envía tus cotizaciones antes."}', 'supervisor@ventel.example', 'Andrés Villalobos', '2026-10-05T20:40:00.000Z');
